// Reduce ancillary work without lowering player input or movement frequency.
export function createFrameBudget(hz=10){let next=-Infinity,key;return {due(now,context){if(context!==key){key=context;next=-Infinity;}if(now<next)return false;next=now+1000/hz;return true;},reset(){next=-Infinity;}};}
export function createFrameWindow(seconds=2.5){let frames=0,time=0;return {sample(dt){if(!Number.isFinite(dt)||dt<=0)return null;if(dt>.5){frames=time=0;return null;}frames++;time+=dt;if(time<seconds)return null;const result={fps:frames/time,seconds:time,frames};frames=time=0;return result;}};}
export function createAnimationBudget(){const states=new WeakMap();return {forget(p){states.delete(p);},step(p,dt,distance=0){let s=states.get(p);if(!s){s={elapsed:0,first:true};states.set(p,s);}s.elapsed+=Math.max(0,dt);const interval=p.rank==='中隊長'||p.nozzle?.visible||distance<=40?0:distance<=100?1/20:distance<=220?1/10:1/5;if(!s.first&&s.elapsed+1e-8<interval)return null;const elapsed=s.elapsed;s.elapsed=0;s.first=false;return Math.min(elapsed,.25);}};}
// Mutable broad phase: exact avoidance tests still use current vehicle positions.
export function createVehicleGrid(cell=32){const cells=new Map(),keys=new WeakMap();const key=(x,z)=>Math.floor(x/cell)+','+Math.floor(z/cell);return {rebuild(vehicles){cells.clear();for(const v of vehicles)if(v.active)this.update(v);},update(v){const k=key(v.x,v.z),old=keys.get(v);if(old!==k)cells.get(old)?.delete(v);let bucket=cells.get(k);if(!bucket)cells.set(k,bucket=new Set());bucket.add(v);keys.set(v,k);},near(x,z,r=30){const out=[];for(let i=Math.floor((x-r)/cell);i<=Math.floor((x+r)/cell);i++)for(let j=Math.floor((z-r)/cell);j<=Math.floor((z+r)/cell);j++)for(const v of cells.get(i+','+j)??[])out.push(v);return out;}};}
